 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # Find the three adjacent nonzero marker cells in a row.
    triple = None
    for r, row in enumerate(grid):
        cells = [c for c, v in enumerate(row) if v]
        for c in cells:
            if c + 1 < w - 1 and row[c] and row[c+1] and row[c+2]:
                triple = (r, c)
                break
        if triple:
            break
    if triple is None:
        return out
    r0, c0 = triple
    colors = [grid[r0][c0+i] for i in range(3)]
    for i, color in enumerate(colors):
        sc = c0 + i
        if i == 1:
            for r in range(r0, h):
                out[r][sc] = color
            continue
        # Join this marker to the matching isolated marker with an L.
        points = [(r, c) for r in range(h) for c in range(w)
                  if grid[r][c] == color and not (r == r0 and c0 <= c <= c0+2)]
        if points:
            rr, cc = points[0]
            for r in range(min(r0, rr), max(r0, rr)+1):
                out[r][sc] = color
            for c in range(min(sc, cc), max(sc, cc)+1):
                out[rr][c] = color
    return out
